1496	        constexpr int KBOX = HD / 64, VBOX = HDV / 64, CB = CN * 64;
1497	        const bool np = (page_table == nullptr);                      // non-paged contiguous KV
1498	        const int pages = np ? 0 : (CN / block_size);
1499	        const uint32_t kv_bytes = (uint32_t)((CN * HD + CN * HDV) * sizeof(TC));
1500	        // COOP gather constants (non-TMA paged persist). FA3 granularity: TPR=8 lanes/row, KIT=HD/64
1501	        // 16B chunks per lane (128-byte coalesced bursts). Barrier-free __shfl page resolve (see prefill_kernel).
1502	        constexpr int TPR = 8, KIT = HD / 64, RPP = WG / TPR, RPT = CN / RPP;
1503	        const int col_th = pt % TPR, rowsub = pt / TPR;
