1554	            // (see prefill_kernel COOP). full[] is inited to NumProd for !USE_TMA, so each lane arrives via
1555	            // cp_async_mbar_arrive (PF_PUBLISH). HD==HDV==128 only (COOP invariant); other HD stay on TMA.
1556	            auto load_kv_coop = [&](int gg, int nb) {
1557	                const int st = gg % STAGES;
1558	                if (gg >= STAGES) { int ep = ((gg / STAGES) - 1) & 1; while (!mbar_try_wait(&empty[st], ep)) {} }
1559	                TC* sKp = sK0 + st * KSTRIDE; TC* sVp = sV0 + st * VSTRIDE;
1560	                const uint32_t sKa = (uint32_t)__cvta_generic_to_shared(sKp);
1561	                const uint32_t sVa = (uint32_t)__cvta_generic_to_shared(sVp);
1562	                int ent = -1;
1563	                if (col_th < RPT) {
